"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["5490"],{7917(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"networks/standards-bodies","title":"Standards Bodies & the RFC Process","description":"Networking works globally because of voluntary, collaborative standards \u2014 no single company or government controls how the Internet\'s protocols work. This page covers the organizations that create and maintain those standards, and the open process behind them.","source":"@site/docs/networks/09-standards-bodies.md","sourceDirName":"networks","slug":"/networks/standards-bodies","permalink":"/Mindstack/docs/networks/standards-bodies","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":9,"frontMatter":{"title":"Standards Bodies & the RFC Process","sidebar_label":"Standards Bodies","sidebar_position":9},"sidebar":"networkSidebar","previous":{"title":"Network Devices","permalink":"/Mindstack/docs/networks/network-devices-overview"},"next":{"title":"Ethernet Fundamentals","permalink":"/Mindstack/docs/networks/ethernet-fundamentals"}}'),r=t(4848),o=t(8453);let a={title:"Standards Bodies & the RFC Process",sidebar_label:"Standards Bodies",sidebar_position:9},s="Standards Bodies & the RFC Process",d={},l=[{value:"Why Standards Matter",id:"why-standards-matter",level:2},{value:"IETF \u2014 Internet Engineering Task Force",id:"ietf--internet-engineering-task-force",level:2},{value:"IETF Organizational Structure",id:"ietf-organizational-structure",level:3},{value:"The RFC Process",id:"the-rfc-process",level:2},{value:"Famous RFCs Worth Knowing",id:"famous-rfcs-worth-knowing",level:3},{value:"IEEE \u2014 Institute of Electrical and Electronics Engineers",id:"ieee--institute-of-electrical-and-electronics-engineers",level:2},{value:"IEEE 802 \u2014 The LAN/MAN Standards Committee",id:"ieee-802--the-lanman-standards-committee",level:3},{value:"ISO \u2014 International Organization for Standardization",id:"iso--international-organization-for-standardization",level:2},{value:"ITU \u2014 International Telecommunication Union",id:"itu--international-telecommunication-union",level:2},{value:"ICANN and IANA \u2014 Internet Naming and Numbering",id:"icann-and-iana--internet-naming-and-numbering",level:2},{value:"Wi-Fi Alliance and Bluetooth SIG \u2014 Industry Consortiums",id:"wi-fi-alliance-and-bluetooth-sig--industry-consortiums",level:2},{value:"How These Bodies Relate \u2014 A Practical Example",id:"how-these-bodies-relate--a-practical-example",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function c(e){let n={a:"a",code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"standards-bodies--the-rfc-process",children:"Standards Bodies & the RFC Process"})}),"\n",(0,r.jsx)(n.p,{children:"Networking works globally because of voluntary, collaborative standards \u2014 no single company or government controls how the Internet's protocols work. This page covers the organizations that create and maintain those standards, and the open process behind them."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"why-standards-matter",children:"Why Standards Matter"}),"\n",(0,r.jsx)(n.p,{children:"Without agreed standards, a device from one manufacturer couldn't communicate with a device from another. Standards bodies solve this coordination problem by publishing open specifications that any vendor can implement, enabling true multi-vendor interoperability \u2014 the entire reason your laptop can connect to a coffee shop's Wi-Fi router from a completely different manufacturer and reach a web server hosted by yet another company, all working flawlessly together."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"ietf--internet-engineering-task-force",children:"IETF \u2014 Internet Engineering Task Force"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'Founded: 1986\nScope:   develops and maintains Internet protocol standards (TCP/IP suite,\n         routing protocols, application protocols, security protocols)\nProcess: open, consensus-driven, working-group based \u2014 "rough consensus\n         and running code" is the famous IETF philosophy: working\n         implementations matter more than theoretical perfection\nOutput:  RFCs (Request for Comments) \u2014 see below\n'})}),"\n",(0,r.jsxs)(n.p,{children:["The IETF has no formal membership \u2014 anyone can participate in working groups, propose drafts, and contribute to discussions, embodying the open, meritocratic culture established by ARPANET's original RFC tradition (see ",(0,r.jsx)(n.a,{href:"/Mindstack/docs/networks/history-of-networking",children:"History of Networking"}),")."]}),"\n",(0,r.jsx)(n.h3,{id:"ietf-organizational-structure",children:"IETF Organizational Structure"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"IETF\n \u251C\u2500\u2500 IESG (Internet Engineering Steering Group) \u2014 manages the standards process\n \u251C\u2500\u2500 IAB  (Internet Architecture Board)          \u2014 oversight, architectural guidance\n \u2514\u2500\u2500 Working Groups \u2014 organized by topic area (Routing, Security, Transport, etc.)\n       Each working group drafts, discusses, and refines proposed standards\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"the-rfc-process",children:"The RFC Process"}),"\n",(0,r.jsxs)(n.p,{children:["A ",(0,r.jsx)(n.strong,{children:"Request for Comments (RFC)"})," is the IETF's standards document format \u2014 despite the informal-sounding name (a holdover from the earliest, genuinely casual ARPANET-era documents), RFCs are the authoritative specifications for virtually every core Internet protocol."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"RFC Lifecycle:\n1. Internet-Draft \u2014 a working proposal, valid for 6 months, can be revised\n2. Working Group review and discussion (often spans months to years)\n3. IESG review\n4. Published as an RFC with a permanent number \u2014 RFCs are NEVER revised or\n   deleted once published; if changes are needed, a NEW RFC supersedes\n   the old one (e.g. RFC 793 defined TCP in 1981; RFC 9293 obsoletes/updates it)\n\nRFC Status Categories:\n  Informational    \u2014 provides information, not a standard\n  Experimental     \u2014 describes experimental protocols/ideas\n  Best Current Practice (BCP) \u2014 recommended practices, not strict protocol specs\n  Standards Track  \u2014 Proposed Standard \u2192 Internet Standard (full maturity)\n  Historic         \u2014 obsolete, no longer recommended\n"})}),"\n",(0,r.jsx)(n.h3,{id:"famous-rfcs-worth-knowing",children:"Famous RFCs Worth Knowing"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'RFC 791   \u2014 Internet Protocol (IPv4), 1981\nRFC 793   \u2014 Transmission Control Protocol (TCP), 1981 (obsoleted by RFC 9293, 2022)\nRFC 1034/1035 \u2014 Domain Name System (DNS), 1987\nRFC 1918  \u2014 Address Allocation for Private Internets (the "private IP ranges"), 1996\nRFC 2131  \u2014 Dynamic Host Configuration Protocol (DHCP), 1997\nRFC 2460  \u2014 Internet Protocol, Version 6 (IPv6), 1998 (obsoleted by RFC 8200, 2017)\nRFC 2616  \u2014 Hypertext Transfer Protocol -- HTTP/1.1, 1999 (later split/obsoleted)\nRFC 4271  \u2014 Border Gateway Protocol 4 (BGP-4), 2006\nRFC 791\'s "be liberal in what you accept, conservative in what you send"\n  (Postel\'s Law) remains one of the most cited design philosophies in\n  protocol engineering, for better and for worse \u2014 it enabled\n  interoperability but also allowed bugs/ambiguity to persist for decades.\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"ieee--institute-of-electrical-and-electronics-engineers",children:"IEEE \u2014 Institute of Electrical and Electronics Engineers"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Founded: 1963 (merger of AIEE and IRE, themselves dating to the 1880s-1910s)\nScope:   broad electrical/electronics engineering standards; for networking,\n         the critical body is IEEE 802, which standardizes LAN/MAN technologies\nProcess: formal voting process among member organizations and individuals,\n         more structured/slower than IETF's rough-consensus model\n"})}),"\n",(0,r.jsx)(n.h3,{id:"ieee-802--the-lanman-standards-committee",children:"IEEE 802 \u2014 The LAN/MAN Standards Committee"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"802.1   \u2014 Bridging and Network Management (includes 802.1Q VLAN tagging,\n          802.1X port-based access control, 802.1D Spanning Tree)\n802.2   \u2014 Logical Link Control (LLC sublayer)\n802.3   \u2014 Ethernet (the most economically significant standard in\n          networking history \u2014 see Ethernet Fundamentals)\n802.5   \u2014 Token Ring (largely historical now)\n802.11  \u2014 Wireless LAN / Wi-Fi (see Wireless Fundamentals)\n802.15  \u2014 Wireless PAN (includes Bluetooth's underlying standard, Zigbee)\n802.16  \u2014 WiMAX (largely superseded by LTE/5G in practice)\n"})}),"\n",(0,r.jsx)(n.p,{children:"802.3 (Ethernet) and 802.11 (Wi-Fi) are, by a wide margin, the two most commercially significant networking standards ever produced by any standards body \u2014 virtually every wired and wireless LAN device on Earth implements one or both."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"iso--international-organization-for-standardization",children:"ISO \u2014 International Organization for Standardization"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Founded: 1947\nScope:   broad international standardization across virtually all\n         industries (not just networking) \u2014 for networking, ISO's most\n         famous contribution is the OSI Reference Model (ISO/IEC 7498)\nProcess: formal, government-backed national standards bodies represent\n         their countries in ISO technical committees \u2014 slower and more\n         bureaucratic than IETF's open working-group model\n"})}),"\n",(0,r.jsxs)(n.p,{children:["ISO's OSI model \"lost\" the protocol wars to TCP/IP in terms of actual implementation, but remains, ironically, ISO's most pedagogically influential networking contribution decades later (full history in ",(0,r.jsx)(n.a,{href:"/Mindstack/docs/networks/history-of-networking",children:"History of Networking"}),")."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"itu--international-telecommunication-union",children:"ITU \u2014 International Telecommunication Union"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Founded: 1865 (originally the International Telegraph Union \u2014 the OLDEST\n         international standards organization still in operation, predating\n         even the telephone)\nScope:   global telecommunications standards, spectrum allocation,\n         satellite orbit coordination \u2014 a specialized agency of the\n         United Nations since 1947\nKey contributions to networking: \n  - E.164 (international telephone numbering plan)\n  - X.25 (early packet-switching standard, historical)\n  - G.65x series (DSL standards)\n  - SDH/SONET (optical transport standards)\n  - Global radio spectrum allocation (relevant to all wireless networking)\n"})}),"\n",(0,r.jsxs)(n.p,{children:["The ITU's telegraph-era origins (1865) make it the oldest organization discussed in this entire reference \u2014 a direct institutional link back to the very beginning of electrical communication described in ",(0,r.jsx)(n.a,{href:"/Mindstack/docs/networks/history-of-networking",children:"History of Networking"}),"."]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"icann-and-iana--internet-naming-and-numbering",children:"ICANN and IANA \u2014 Internet Naming and Numbering"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"IANA (Internet Assigned Numbers Authority) \u2014 founded informally in the\n  1970s (originally run by Jon Postel at USC), formalized later \u2014 manages:\n  - IP address allocation (to Regional Internet Registries, who then\n    allocate to ISPs/organizations)\n  - Autonomous System Number (ASN) allocation (used in BGP)\n  - Protocol parameter registries (port numbers, EtherTypes, etc.)\n  - The DNS root zone\n\nICANN (Internet Corporation for Assigned Names and Numbers) \u2014 founded\n  1998, a nonprofit that oversees IANA's functions and coordinates the\n  DNS root system and domain name policy globally \u2014 created specifically\n  to transition these functions away from direct U.S. government contract\n  oversight toward a more international, multi-stakeholder model\n\nRegional Internet Registries (RIRs) \u2014 allocate IP address blocks within\n  their geographic region:\n    ARIN   \u2014 North America\n    RIPE NCC \u2014 Europe, Middle East, parts of Central Asia\n    APNIC  \u2014 Asia-Pacific\n    LACNIC \u2014 Latin America and Caribbean\n    AFRINIC \u2014 Africa\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"wi-fi-alliance-and-bluetooth-sig--industry-consortiums",children:"Wi-Fi Alliance and Bluetooth SIG \u2014 Industry Consortiums"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'Wi-Fi Alliance \u2014 a trade association (not a formal standards body) that\n  certifies interoperability of 802.11-based products and created the\n  consumer-friendly "Wi-Fi" brand name and generational naming (Wi-Fi 4,\n  5, 6, 6E, 7) on top of the more technical IEEE 802.11 standard numbers\n  (802.11n, ac, ax, be) \u2014 IEEE defines the technical standard, the\n  Wi-Fi Alliance certifies and markets it\n\nBluetooth SIG (Special Interest Group) \u2014 similarly manages the Bluetooth\n  standard and certifies device interoperability\n'})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"how-these-bodies-relate--a-practical-example",children:"How These Bodies Relate \u2014 A Practical Example"}),"\n",(0,r.jsx)(n.p,{children:"To understand how multiple standards bodies cooperate on a single piece of technology, consider connecting to Wi-Fi:"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'1. IEEE 802.11 defines the technical radio/MAC layer standard\n2. Wi-Fi Alliance certifies your device as interoperable, branding it "Wi-Fi 6"\n3. ITU coordinates international radio spectrum allocation so the 2.4/5/6 GHz\n   bands are consistently available for this use worldwide\n4. IETF protocols (DHCP, TCP/IP, DNS, HTTP) run ON TOP of that wireless link\n   to actually deliver your web request\n5. ICANN/IANA\'s DNS root and IP allocation systems make sure the domain\n   name you typed resolves to a globally unique, reachable IP address\n'})}),"\n",(0,r.jsx)(n.p,{children:"This layered cooperation across multiple independent standards bodies \u2014 none of which directly controls the others \u2014 is precisely why the Internet works as a single, coherent global system despite having no central owner."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:'When researching a protocol\'s exact specification, search for its RFC number directly (e.g. "RFC 793") rather than relying solely on secondary summaries \u2014 RFCs are the authoritative source.'}),"\n",(0,r.jsx)(n.li,{children:"Remember the IEEE 802.X numbering pattern: 802.1 = bridging/management, 802.3 = Ethernet, 802.11 = wireless \u2014 these three are referenced constantly in real-world networking documentation and configuration."}),"\n",(0,r.jsx)(n.li,{children:'"Wi-Fi 6" (marketing name) = 802.11ax (technical standard) \u2014 knowing both naming conventions helps when reading older documentation that predates the Wi-Fi Alliance\'s generational rebrand (introduced in 2018).'}),"\n"]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"The IETF (via open RFCs) standardizes the core Internet protocol suite (TCP/IP, routing, DNS, HTTP); the IEEE (via 802 committees) standardizes LAN/MAN technologies (Ethernet, Wi-Fi)."}),"\n",(0,r.jsx)(n.li,{children:"RFCs are never edited after publication \u2014 superseding documents obsolete older ones, preserving a complete historical record of protocol evolution."}),"\n",(0,r.jsx)(n.li,{children:"ISO produced the OSI model, which lost the real-world implementation race to TCP/IP but remains the dominant conceptual teaching framework."}),"\n",(0,r.jsx)(n.li,{children:"The ITU, dating to 1865, is the oldest standards body discussed here, with roots in international telegraph coordination."}),"\n",(0,r.jsx)(n.li,{children:"IANA/ICANN and the five Regional Internet Registries manage the global allocation of IP addresses and AS numbers, the numbering infrastructure that makes global routing (BGP) possible."}),"\n",(0,r.jsx)(n.li,{children:"No single organization controls the Internet \u2014 its function depends on voluntary, open cooperation between many independent standards bodies, each responsible for a different layer or aspect of the overall system."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>s});var i=t(6540);let r={},o=i.createContext(r);function a(e){let n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),i.createElement(o.Provider,{value:n},e.children)}}}]);